using System;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Text;using System.Xml;using System.Threading;using System.Threading.Tasks;
namespace BeamScheduleFormatter {
class WindDesignForm:DesignSheetForm {
 readonly Label speed=new Label{AutoSize=false,Width=900,Height=80,Tag="FullWidth",Font=new Font("Segoe UI",13,FontStyle.Bold),ForeColor=Color.Teal};readonly Label status=new Label{Width=900,Height=70,Tag="FullWidth"};readonly WindMapControl preview=new WindMapControl{Dock=DockStyle.Right,Width=350},map=new WindMapControl{Dock=DockStyle.Fill};readonly DataGridView results=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=Color.White,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};readonly WindProfileControl[] plots=new WindProfileControl[8];readonly System.Windows.Forms.Timer debounce=new System.Windows.Forms.Timer{Interval=700};CancellationTokenSource pending;WindTerrain terrain;bool closed;
 public WindDesignForm():base("Wind Load | NSCP 2015","Wind-Design"){
 var input=Section("Site & map","Enter decimal latitude and longitude. Speed comes from the workbook's wind contours using Delaunay TIN. Terrain/exposure are preliminary assessments from public DEM/land-cover data. Default z=10m is a reference, not an inferred building height.");NumberField(input,"Latitude","Latitude N (decimal degrees)","");NumberField(input,"Longitude","Longitude E (decimal degrees)","");var category=Choice(input,"Category","NSCP Occupancy Category",new[]{"I","II","III-V"});category.SelectedItem="III-V";NumberField(input,"Height","Height above local ground z (m)","10");NumberField(input,"Kd","Directionality factor Kd","0.85");Toggle(input,"Reviewed","Terrain / roughness evidence reviewed",false);input.Controls.Add(speed);input.Controls.Add(status);var tools=new FlowLayoutPanel{Width=900,Height=44,Tag="FullWidth"};var load=new Button{Text="Load / refresh site terrain",AutoSize=true};load.Click+=async(s,e)=>await LoadTerrain();tools.Controls.Add(load);input.Controls.Add(tools);var sitePage=(TabPage)input.Parent;sitePage.Controls.Add(preview);sitePage.Controls.SetChildIndex(input,0);
 var mapPage=new TabPage("Embedded wind map / TIN");mapPage.Controls.Add(map);Pages.TabPages.Insert(Pages.TabCount-1,mapPage);var output=new TabPage("8-direction calculations");foreach(string name in new[]{"Wind from","Suggested exposure","Feature","H m","Lh m","x m","K1","K2","K3","Kzt","Kz","qz kPa","Assessment / review"})results.Columns.Add(name,name);results.Columns[12].MinimumWidth=500;results.ColumnHeadersHeight=48;output.Controls.Add(results);Pages.TabPages.Insert(Pages.TabCount-1,output);var profiles=new TabPage("Terrain profiles");var tabs=new TabControl{Dock=DockStyle.Fill};for(int i=0;i<8;i++){var page=new TabPage(WindAssessment.Directions[i]);plots[i]=new WindProfileControl{Dock=DockStyle.Fill};page.Controls.Add(plots[i]);tabs.TabPages.Add(page);}profiles.Controls.Add(tabs);Pages.TabPages.Insert(Pages.TabCount-1,profiles);
 foreach(string key in new[]{"Latitude","Longitude"})Inputs[key].TextChanged+=(s,e)=>{if(Restoring)return;terrain=null;((CheckBox)Inputs["Reviewed"]).Checked=false;if(pending!=null)pending.Cancel();UpdateResults();debounce.Stop();if(ValidCoordinates())debounce.Start();};category.SelectedIndexChanged+=(s,e)=>{if(!Restoring)UpdateResults();};Inputs["Height"].TextChanged+=(s,e)=>{if(!Restoring)UpdateResults();};Inputs["Kd"].TextChanged+=(s,e)=>{if(!Restoring)UpdateResults();};debounce.Tick+=async(s,e)=>{debounce.Stop();await LoadTerrain();};FormClosed+=(s,e)=>{closed=true;debounce.Dispose();if(pending!=null)pending.Cancel();};preview.ShowSource(27);map.ShowSource(27);speed.Text="Enter coordinates to calculate wind speed.";status.Text="Map visible before input. Terrain loads online once, then Save sheet XML keeps profiles for offline use.";
 }
 bool ValidCoordinates(){try{WindTin.Validate(Number("Latitude"),Number("Longitude"));return true;}catch{return false;}}
 static string F(double n){return WindTin.Finite(n)?n.ToString("0.###",CultureInfo.InvariantCulture):"Unresolved";}
 void UpdateResults(){results.Rows.Clear();foreach(var p in plots){p.Data=null;p.Invalidate();}int image=Value("Category")=="I"?29:Value("Category")=="II"?28:27;preview.ShowSource(image);map.ShowSource(image);try{var value=WindTin.At(Number("Latitude"),Number("Longitude"),Value("Category"));preview.ShowResult(value);map.ShowResult(value);speed.Text="Basic wind speed: "+value.V.ToString("0.0",CultureInfo.InvariantCulture)+" km/h ("+(value.V/3.6).ToString("0.00",CultureInfo.InvariantCulture)+"m/s)\r\n"+(value.Coastal?"Coastal contour continuation — verify map.":"Delaunay TIN interpolation — source-map accuracy applies.");if(terrain==null)return;var calculated=WindAssessment.Calculate(terrain,Number("Height"),value.V,Number("Kd"));for(int i=0;i<8;i++){var d=calculated[i];results.Rows.Add(d.Name,d.Exposure,d.Shape,F(d.H),F(d.Lh),F(d.X),F(d.K1),F(d.K2),F(d.K3),F(d.Kzt),F(d.Kz),F(d.Qz),d.Status);plots[i].Data=d;plots[i].Invalidate();}}catch(Exception ex){speed.Text="Enter valid parameters: "+ex.Message;}}
 async Task LoadTerrain(){if(closed||!ValidCoordinates())return;double lat=Number("Latitude"),lon=Number("Longitude"),height;try{height=Number("Height");if(height<=0||height>150)throw new Exception("Enter z between 0 and 150m.");}catch(Exception ex){status.Text=ex.Message;return;}if(pending!=null)pending.Cancel();var token=new CancellationTokenSource();pending=token;status.Text="Loading public terrain and land cover for eight directions…";try{double radius=Math.Ceiling(Math.Max(3200,40*height+1000)/100)*100;var progress=new Progress<string>(text=>{if(!closed&&pending==token)status.Text=text;});var data=await Task.Run(()=>new WindTerrainClient().Load(lat,lon,radius,token.Token,progress));if(closed||pending!=token||token.IsCancellationRequested)return;terrain=data;status.Text="Terrain loaded. Review the suggested exposure/feature applicability, then save sheet XML for offline use.";UpdateResults();}catch(Exception ex){if(!closed&&pending==token&&!token.IsCancellationRequested)status.Text="Terrain unavailable: "+ex.Message+" Speed map remains available; factors are not defaulted.";}finally{if(pending==token)pending=null;token.Dispose();}}
 protected override string BuildReport(){return WindReport.Build(Number("Latitude"),Number("Longitude"),Value("Category"),Number("Height"),Number("Kd"),terrain,((CheckBox)Inputs["Reviewed"]).Checked);}
 protected override void WriteAdditionalState(XmlElement root){WindTerrainXml.Write(root,terrain);}
 protected override void ReadAdditionalState(XmlElement root){if(pending!=null)pending.Cancel();terrain=WindTerrainXml.Read(root);}
 protected override void AfterRestore(){UpdateResults();status.Text=terrain==null?"Coordinates restored. Load site terrain for factors.":"Saved terrain profiles restored for offline use; review data age/site conditions.";}
}
class WindMapControl:UserControl {
 readonly Panel scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};readonly PictureBox picture=new PictureBox{SizeMode=PictureBoxSizeMode.StretchImage};readonly TrackBar zoom=new TrackBar{Dock=DockStyle.Top,Minimum=1,Maximum=5,Value=1,Height=40};int source;WindLookup point;
 public WindMapControl(){Controls.Add(scroll);Controls.Add(zoom);scroll.Controls.Add(picture);zoom.ValueChanged+=(s,e)=>ResizeMap();scroll.Resize+=(s,e)=>ResizeMap();picture.Paint+=(s,e)=>{if(point==null||picture.Image==null)return;float sx=picture.Width/3179f,sy=picture.Height/4801f,x=(float)point.X*sx,y=(float)point.Y*sy;using(var pen=new Pen(Color.MediumVioletRed,2)){if(point.Nodes.Length==3)e.Graphics.DrawPolygon(pen,point.Nodes.Select(n=>new PointF((float)n.X*sx,(float)n.Y*sy)).ToArray());e.Graphics.DrawLine(pen,x-9,y,x+9,y);e.Graphics.DrawLine(pen,x,y-9,x,y+9);e.Graphics.DrawEllipse(pen,x-5,y-5,10,10);}};Disposed+=(s,e)=>{if(picture.Image!=null)picture.Image.Dispose();};}
 public void ShowSource(int number){point=null;if(source!=number){using(var stream=typeof(WindTin).Assembly.GetManifestResourceStream("WindMap"+number+".jpg")){if(stream==null)throw new Exception("Embedded wind map is missing.");using(var image=Image.FromStream(stream)){var old=picture.Image;picture.Image=new Bitmap(image,new Size(1600,2416));if(old!=null)old.Dispose();}}source=number;}ResizeMap();picture.Invalidate();}
 public void ShowResult(WindLookup value){if(source!=value.Map)ShowSource(value.Map);point=value;picture.Invalidate();}
 void ResizeMap(){if(picture.Image==null)return;int height=Math.Max(240,scroll.ClientSize.Height-20)*zoom.Value;picture.Size=new Size((int)(height*3179.0/4801),height);}
}
class WindProfileControl:Control {
 public WindDirection Data;public WindProfileControl(){DoubleBuffered=true;BackColor=Color.White;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;var d=Data;if(d==null){g.DrawString("Load site terrain to view the profile. Missing data is not plotted as zero.",Font,Brushes.DimGray,15,20);return;}var points=d.Profile.Where(p=>WindTin.Finite(p.Z)).ToList();if(points.Count<2)return;double min=points.Min(p=>p.Z),max=points.Max(p=>p.Z);if(max-min<2){min--;max++;}float left=70,top=75,w=Math.Max(100,Width-110),h=Math.Max(100,Height-170);double first=points.First().D,last=points.Last().D;Func<double,float> x=v=>left+(float)((v-first)/(last-first)*w);Func<double,float> y=v=>top+h-(float)((v-min)/(max-min)*h);g.DrawString(d.Name+" wind-from | suggested exposure "+d.Exposure+" | "+d.Shape+" | Kzt "+(WindTin.Finite(d.Kzt)?d.Kzt.ToString("0.###"):"unresolved"),Font,Brushes.Black,15,15);g.DrawString("Elevation m | site at 0 | positive distance = upwind | green potential B / yellow C / blue water D",Font,Brushes.DimGray,15,42);for(int i=0;i<6;i++){double z=min+(max-min)*i/5;g.DrawLine(Pens.Gainsboro,left,y(z),left+w,y(z));g.DrawString(z.ToString("0.#"),Font,Brushes.DimGray,3,y(z)-7);}using(var pen=new Pen(Color.SteelBlue,2))g.DrawLines(pen,points.Select(p=>new PointF(x(p.D),y(p.Z))).ToArray());g.DrawLine(Pens.Firebrick,x(0),top,x(0),top+h);for(int i=0;i<points.Count-1;i++){Brush brush=WindAssessment.Roughness(points[i].Cover)=="B"?Brushes.ForestGreen:WindAssessment.Roughness(points[i].Cover)=="D"?Brushes.DodgerBlue:Brushes.Goldenrod;g.FillRectangle(brush,x(points[i].D),top+h+8,Math.Max(1,x(points[i+1].D)-x(points[i].D)),8);}for(int i=0;i<=8;i++){double v=first+(last-first)*i/8;g.DrawString((v/1000).ToString("0.#")+"km",Font,Brushes.DimGray,x(v)-20,top+h+23);}g.DrawString(d.Status,Font,Brushes.DimGray,new RectangleF(15,Height-45,Width-30,40));}
}
static class WindReport {
 static string F(double n){return WindTin.Finite(n)?n.ToString("0.######",CultureInfo.InvariantCulture):"UNRESOLVED";}
 public static string Build(double lat,double lon,string category,double z,double kd,WindTerrain terrain,bool reviewed){if(!WindTin.Finite(z)||z<=0||z>150||!WindTin.Finite(kd)||kd<=0||kd>1)throw new Exception("Check reference height and Kd.");var wind=WindTin.At(lat,lon,category);var b=new StringBuilder();b.AppendLine("DTCE | NSCP 2015 WIND SITE CALCULATION");b.AppendLine("Source: owner-supplied RCB Wind v.3.3.xlsm, embedded Figure207A.5-1 maps.");b.AppendLine(reviewed?"Terrain evidence reviewed by user; raster wind-speed accuracy remains approximate.":"PRELIMINARY: automatic terrain/exposure candidates require site review.");b.AppendLine("Latitude "+F(lat)+", longitude "+F(lon)+"; NSCP Occupancy Category "+category+"; z="+F(z)+"m; Kd="+F(kd));b.AppendLine("V="+F(wind.V)+"km/h = "+F(wind.V/3.6)+"m/s. Reference3-second gust at10m, Exposure C. CategoryI essential/highest, II intermediate, III-V lower.");b.AppendLine("Map image "+wind.Map+"; pixel("+F(wind.X)+","+F(wind.Y)+"); triangle "+wind.Triangle);b.AppendLine(wind.Coastal?"OUTSIDE TIN HULL: nearest-contour coastal continuation; verify applicable contour. Not a TIN interpolation.":"Delaunay TIN: V=sum(w_i V_i), full-precision barycentric weights.");for(int i=0;i<wind.Nodes.Length;i++)b.AppendLine("Node "+(i+1)+": ("+F(wind.Nodes[i].X)+","+F(wind.Nodes[i].Y)+")px, V="+F(wind.Nodes[i].V)+", w="+F(wind.Weights[i]));b.AppendLine("Raster registration: Web Mercator fitted to Natural Earth1:10m coastline, median residual1.51px, p90=3.77px. 12px contour sampling introduces further digitization error. This is not exact or an authoritative georeferenced wind dataset. Special wind regions need separate investigation.");if(terrain==null||Math.Abs(terrain.Lat-lat)>1e-8||Math.Abs(terrain.Lon-lon)>1e-8){b.AppendLine("No matching terrain snapshot: Kzt/exposure/qz remain unresolved.");return b.ToString();}b.AppendLine("Terrain acquired UTC: "+terrain.Acquired.ToUniversalTime().ToString("o")+"; radius="+F(terrain.Radius)+"m. AWS Terrarium z12 elevation mosaic (~30–40m sampling), ESA WorldCover2021v20010m.");b.AppendLine("Sources: https://registry.opendata.aws/terrain-tiles/ ; https://github.com/tilezen/joerd/blob/master/docs/attribution.md ; ESA WorldCover2021(CC BY4.0): https://doi.org/10.5281/zenodo.7254221");b.AppendLine("Exposure screening uses3 rays per45deg wind-from sector at100m spacing. Land cover cannot establish obstruction heights or complete sector coverage. Potential B=trees/built-up/mangroves, D=mapped water, C=other supported classes. Confirm roughness B obstructions >=9.1m and D smooth/unobstructed conditions.");b.AppendLine("B fetch: h<=9.1m->457.2m, otherwise max(792.48m,20h). D smooth fetch=max(1524m,20h), transition=max(609.6m,20h). No-data does not silently default to C.");b.AppendLine("Kzt=(1+K1 K2 K3)^2; K1=A*min(H/Lh,0.5), effectiveLh=max(Lh,2H); K2=max(0,1-|x|/(mu Lh)); K3=exp(-gamma*z/Lh). x>0 windward, x<0 leeward. A[B,C,D]: hill[.95,1.05,1.15], ridge[1.30,1.45,1.55], escarpment[.75,.85,.95]. gamma=4/3/2.5; mu=1.5 except leeward escarpment4.");b.AppendLine("Topographic triggers: H>=18.288m for B,4.572m for C/D; H/Lh>=0.2 and upper-half criterion. DEM-derived shape/crest/half-height are candidates; verify isolation and upwind similar-height terrain within100H/3.2km. DEMs may contain canopy/building artifacts.");b.AppendLine("Kz=2.01(max(z,4.572)/zg)^(2/alpha); B[7,365.76], C[9.5,274.32], D[11.5,213.36]. qz=.613 Kz Kzt Kd(V/3.6)^2/1000 kPa is VELOCITY PRESSURE, not final roof/wall net pressure. Geometry, external/internal coefficients and gust effects still apply.");foreach(var d in WindAssessment.Calculate(terrain,z,wind.V,kd)){b.AppendLine();b.AppendLine(d.Name+" | suggested exposure "+d.Exposure+" | "+d.Shape+" | "+d.Status);b.AppendLine("H="+F(d.H)+"m, Lh="+F(d.Lh)+"m, x="+F(d.X)+"m; K1="+F(d.K1)+", K2="+F(d.K2)+", K3="+F(d.K3)+", Kzt="+F(d.Kzt)+", Kz="+F(d.Kz)+", qz="+F(d.Qz)+"kPa");b.AppendLine("Profile: signed distance m | elevation m | land cover code");foreach(var p in d.Profile)b.AppendLine(F(p.D)+" | "+F(p.Z)+" | "+p.Cover);}return b.ToString();}
}
